message.__transform:
(

$q :=  $query({
    "api": "application",
      "statement":"query ModeList{modeList(where: {modeGroupId: {_eq:\"" & rowData.id & "\"}}) { total\n }}"
    });


$q.modeList.total > 0 

? rowData.name & " is configured with " & $q.modeList.total & " modes. Are you sure you would like to proceed?"
: "Are you sure you would like to delete mode group " & rowData.name & "?"
)

transforms.pre:
(

$q :=  $query({
    "api": "application",
      "statement":"query ModeList{modeList(where: {modeGroupId: {_eq:\"" & rowData.id & "\"}}) { total\n edges{\n node{\n id} }}}"
    });


$modeListOrEmpty :=  $q.modeList.total > 0 ? $q.modeList.edges.{
    "where": {
      "id": $.node.id
    }
  } : [];
{ 
  "payloadModeList": $modeListOrEmpty,
  "payloadModeGroup": {
    "where": {
      "id": rowData.id
    }
  }
}
)

action.transformation:
(

/* set form data */
$components.MainForm.fn.setValue("name",$$.name);
$components.MainForm.fn.setValue("id",$$.mutation.id);

/* set modelist table to load (should be empty as it is new mode group) */
$components.ModeListTable.fn.loadData({
  "filter": {
    "modeGroupId": {
      "_eq": $$.mutation.id
    }
  }

});

/* reload mode group table */
$components.ModeGroupTable.fn.search()

)

$isNil($.MainForm.formState.values.viewUnusable) or $.MainForm.formState.values.viewUnusable=false
?
(
  $.MainForm.fn.setValue("viewUnusable", true);
   $q := $query({
    "api": "application",
      "statement":"query Mode{mode{ total \nedges{ \nnode{id \nname \nusable \nincludeInOee \nincludeProductionCounts \noperatingTimeInclude \nproductionExpected \nrequireEvent \nexternalId modeType{id \nname} } }}}"
    });
  $.ModeTable.fn.setData($q.mode.edges.node);
)
:
(
 $.MainForm.fn.setValue("viewUnusable", false);
$.ModeTable.fn.search()
)
